// App-normalized result model; not SDK type names.
when (interactionResult) {
    is NeedFields -> showFields(interactionResult.fields) { values ->
        interactionResult.continueWith(values)
    }
    is Cancelled -> clearPendingInteraction()
    is Failed -> showSanitizedFailure(interactionResult)
    is Completed -> verifyTerminalSdkState()
}

ios.code:
// App-normalized result model; not SDK type names.
switch interactionResult {
case .needFields(let fields, let continuation):
    showFields(fields) { values in continuation(values) }
case .cancelled: clearPendingInteraction()
case .failed(let error): showSanitizedFailure(error)
case .completed: verifyTerminalSDKState()
}
